-- Stores Yu-Gi-Oh card drafts.
-- `id` is generated by the app (string).
-- `img_url` is a URL pointing to the image stored elsewhere.

CREATE TABLE IF NOT EXISTS yugioh_cards (
  id TEXT PRIMARY KEY,

  name TEXT NOT NULL,
  card_type TEXT NOT NULL CHECK (card_type IN ('Monster', 'Spell', 'Trap', 'Field')),
  description TEXT NOT NULL DEFAULT '',

  -- Kept as NOT NULL to match the current TS draft type shape
  attribute TEXT,

  monster_type TEXT,
  sub_type TEXT,
  is_tuner BOOLEAN,

  level INTEGER NOT NULL DEFAULT 0,
  atk INTEGER NOT NULL DEFAULT 0,
  def INTEGER NOT NULL DEFAULT 0,

  spell_type TEXT,
  trap_type TEXT,

  img_url TEXT,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
